#!/usr/bin/env python3
"""Build 5e SRD and Cyberpunk RED kit catalogs."""
from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data"


def slug(name: str) -> str:
    s = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    return s or "item"


def I(**kw):
    kw["id"] = kw.get("id") or slug(kw["name"])
    return {k: v for k, v in kw.items() if v not in (None, "", [], {})}


KIND_ORDER = ["weapon", "armor", "gear", "magic", "chrome", "quickhack", "spell"]


def dump(name: str, rows: list[dict]) -> None:
    seen = set()
    out = []
    for row in rows:
        base = row["id"]
        i = base
        n = 2
        while i in seen:
            i = f"{base}-{n}"
            n += 1
        row = {**row, "id": i}
        seen.add(i)
        out.append(row)
    out.sort(
        key=lambda r: (
            KIND_ORDER.index(r["kind"]) if r.get("kind") in KIND_ORDER else 99,
            str(r.get("name") or "").casefold(),
        )
    )
    path = OUT / name
    path.write_text(json.dumps(out, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
    print(f"{name}: {len(out)}  {path.stat().st_size} bytes")


